ORDER = ['BLOG-377', 'BLOG-378', 'BLOG-379', 'BLOG-380', 'BLOG-381', 'BLOG-382', 'BLOG-383', 'BLOG-384', 'BLOG-385', 'BLOG-386', 'BLOG-387']


def main():
    with io.open(BULLET, encoding='utf-8') as f:
        bullet = f.read().strip('\n').rstrip(' ')
    assert bullet.startswith('- **第380回:'), 'bullet format check failed'
    assert '\n' not in bullet, 'bullet must be single line'

    # --- README ---
    with io.open(README, encoding='utf-8') as f:
        readme = f.read()
    if '- **第380回:' in readme:
        print('README: 第380回bullet already present; skip')
    else:
        lines = readme.split('\n')
        hits = [i for i, l in enumerate(lines) if l.startswith('- **第379回:')]
        assert len(hits) == 1, 'README anchor 第379回 found %d' % len(hits)
        lines.insert(hits[0] + 1, bullet)
        with io.open(README, 'w', encoding='utf-8', newline='') as f:
            f.write('\n'.join(lines))
        print('README: bullet inserted after line %d' % (hits[0] + 1))

    # --- INDEX ---
    with io.open(INDEX, encoding='utf-8') as f:
        index = f.read()
    if 'BLOG-377' in index:
        print('INDEX: BLOG-377 already present; skip')
    else:
        assert '## ブログ・個人サイト（375件）' in index, 'INDEX ブログ heading mismatch'
        assert '資料ファイル総数: 1959件' in index, 'INDEX 総数 mismatch'
        lines = index.split('\n')
        bhits = [i for i, l in enumerate(lines) if l.startswith('- [BLOG-376]')]
        assert len(bhits) == 1, 'INDEX anchor BLOG-376 found %d' % len(bhits)
        pos = bhits[0] + 1
        for k in ORDER:
            lines.insert(pos, LINES[k])
            pos += 1
        index = '\n'.join(lines)
        index = index.replace('## ブログ・個人サイト（375件）', '## ブログ・個人サイト（386件）')
        index = index.replace('資料ファイル総数: 1959件', '資料ファイル総数: 1970件')
        with io.open(INDEX, 'w', encoding='utf-8', newline='') as f:
            f.write(index)
        print('INDEX: BLOG-377..387 inserted; counts updated')


if __name__ == '__main__':
    main()
